lesson.content:

\begin{definition} 
    \textbf{Proposición}. Una proposición es una declaración que puede ser verdadera o falsa, pero no ambas.
\end{definition}

Ejemplos:

\begin{itemize}
    \item "El cielo es azul." (Verdadera)
    \item "2 + 2 = 5." (Falsa)
    \item "¿Qué hora es?" (No es una proposición)
\end{itemize}
